import * as THREE from './vendor/three.module.js';
// Soft projected irradiance keeps distant lights visible without allocating a light per car/lamp.
// Nearby sources also use real PointLight/SpotLight objects in night-lighting.js.
export function createLightField(parent,count,{beam=false,color=0xffe0a6}={}){
 const geometry=new THREE.PlaneGeometry(2,2);geometry.rotateX(-Math.PI/2);const tints=new Float32Array(count*3),powers=new Float32Array(count);const c=new THREE.Color(color);for(let i=0;i<count;i++){c.toArray(tints,i*3);powers[i]=1}geometry.setAttribute('fieldTint',new THREE.InstancedBufferAttribute(tints,3));geometry.setAttribute('fieldPower',new THREE.InstancedBufferAttribute(powers,1));
 const strength={value:0},wetness={value:0},clock={value:0};const material=new THREE.ShaderMaterial({transparent:true,depthWrite:false,blending:THREE.AdditiveBlending,side:THREE.DoubleSide,toneMapped:false,fog:true,uniforms:{...THREE.UniformsUtils.clone(THREE.UniformsLib.fog),strength,wetness,clock},
 vertexShader:'attribute vec3 fieldTint; attribute float fieldPower; varying vec2 vUv; varying vec3 vTint; varying float vPower;\n#include <fog_pars_vertex>\nvoid main(){vUv=uv;vTint=fieldTint;vPower=fieldPower;vec4 mvPosition=modelViewMatrix*instanceMatrix*vec4(position,1.0);gl_Position=projectionMatrix*mvPosition;\n#include <fog_vertex>\n}',
 fragmentShader:`uniform float strength;uniform float wetness;uniform float clock;varying vec2 vUv;varying vec3 vTint;varying float vPower;\n#include <fog_pars_fragment>\nvoid main(){vec2 p=(vUv-.5)*2.;float alpha;${beam?'float forward=1.-vUv.y;float width=.16+forward*.84;alpha=pow(max(0.,1.-abs(p.x)/width),1.8)*pow(1.-forward,1.5)*smoothstep(0.,.07,forward);':'alpha=pow(max(0.,1.-length(p)),2.);'}float ripple=1.-wetness*.15+wetness*.15*sin(vUv.y*65.+sin(vUv.x*32.+clock*.4));gl_FragColor=vec4(vTint,alpha*strength*vPower*ripple);\n#include <colorspace_fragment>\n#include <fog_fragment>\n}`});
 const mesh=new THREE.InstancedMesh(geometry,material,count);mesh.name=beam?'Headlight footprints on asphalt':'Soft light on pavement';mesh.frustumCulled=false;mesh.renderOrder=3;parent.add(mesh);const dummy=new THREE.Object3D();
 return{mesh,geometry,material,strength,wetness,clock,tints,powers,set(index,x,y,z,rx,rz,heading=0,tint=null,power=1){dummy.position.set(x,y,z);dummy.rotation.set(0,heading,0);dummy.scale.set(rx,1,rz);dummy.updateMatrix();mesh.setMatrixAt(index,dummy.matrix);if(tint)tint.toArray(tints,index*3);powers[index]=power},commit(){mesh.instanceMatrix.needsUpdate=true;geometry.attributes.fieldTint.needsUpdate=true;geometry.attributes.fieldPower.needsUpdate=true},dispose(){geometry.dispose();material.dispose();parent.remove(mesh)}};
}
